{																																															\
	using Iter = std::remove_cvref_t<decltype(self.begin())>;																																\
	for (Iter pBegin{ self.begin() }, pChar{ self.end() };;)																																\
	{																																														\
		if (pChar == pBegin)return Iter{};																																					\
		--pChar;																																											\
		if (*pChar == c)return pChar;																																						\
	}																																														\
}																																															\
