//template<class T, auto...args>INLINE constexpr bool operator>(const Opt<T, args...>& l, const Opt<T, args...>& r)noexcept { return l && r && *l > *r; }
//template<class T, auto...args>INLINE constexpr bool operator<=(const Opt<T, args...>& l, const Opt<T, args...>& r)noexcept { return l && r && *l <= *r; }
