	struct RtlBalancedNode
	{
		union
		{
			struct RtlBalancedNode* Children[2];                             //0x0
			struct
			{
				struct RtlBalancedNode* Left;                                //0x0
				struct RtlBalancedNode* Right;                               //0x8
			};
		};
		union
		{
			struct
			{
				u8 Red : 1;                                                    //0x10
				u8 Balance : 2;                                                //0x10
			};
			usize ParentValue;                                              //0x10
		};
	};

